# Try extracting a specific color pattern - let's see '1' positions
input_grid = [
    [1, 5, 5, 7, 5, 3, 1],
    [5, 5, 3, 3, 1, 1, 7],
    [0, 1, 5, 7, 5, 5, 5],
    [5, 5, 3, 5, 7, 5, 5],
    [1, 9, 5, 7, 1, 5, 5],
    [5, 5, 5, 5, 1, 5, 5],
    [5, 5, 5, 1, 0, 5, 5],
    [5, 1, 9, 7, 1, 5, 5]
]

# Get positions of each non-5 color
colors = {}
for r, row in enumerate(input_grid):
    for c, val in enumerate(row):
        if val != 5:
            if val not in colors:
                colors[val] = []
            colors[val].append((r, c))

print("Positions by color (value → list of (row, col)):")
for c in sorted(colors.keys()):
    print(f"  {c}: {colors[c]}")
